def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    current = data
    for key in key_path:
        if key not in current:
            raise KeyError(f"Key '{key}' not found")
        current = current[key]
    if not isinstance(current, list):
        current = [current]
    numeric_values = []
    for item in current:
        if isinstance(item, (int, float)):
            numeric_values.append(item)
        elif isinstance(item, str):
            item = item.strip()
            if not item:
                raise ValueError("Data string is empty or corrupted")
            try:
                numeric_values.append(float(item))
            except ValueError:
                raise ValueError("Data string is empty or corrupted")
        else:
            raise ValueError("No numeric data found")
    if len(numeric_values) == 0:
        raise ValueError("No numeric data found")
    df = pd.DataFrame({'values': numeric_values})
    fig, ax = plt.subplots()
    sns.boxplot(data=df, y='values', ax=ax)
    return fig

import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")
    if not data:
        raise ValueError("Empty JSON data")
    if not isinstance(data, list):
        raise ValueError("JSON data must be a list")
    countries = []
    populations = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item must be a dictionary")
        if "country" not in item or "population" not in item:
            raise ValueError("Each item must have 'country' and 'population' keys")
        country = item["country"]
        population = item["population"]
        if not isinstance(country, str):
            raise ValueError("Country must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        if isinstance(population, float):
            population = math.floor(population)
        countries.append(country)
        populations.append(population)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except IOError:
        raise IOError("Cannot write file to specified directory")
    return file_path, df

import numpy as np
from collections import defaultdict
import json
import csv
def task_func(input_file, output_file):
    with open(input_file, 'r') as f:
        data = json.load(f)

    stats = defaultdict(list)
    for d in data:
        for key, value in d.items():
            stats[key].append(value)

    result = {}
    for key, values in stats.items():
        result[key] = {
            'mean': float(np.mean(values)),
            'median': float(np.median(values))
        }

    with open(output_file, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['key', 'mean', 'median'])
        for key, values in result.items():
            writer.writerow([key, values['mean'], values['median']])

    return result
